  "use strict";
  var node = typeof module !== "undefined" && module.exports;
  var core = node ? require("./drill-core.js") : G.TOKOS_DRILL_CORE;
  var model = core.make({"id":"mh","kind":"drill","level":"resident","review":"ai_drafted","timeLimitSec":600,"title":{"en":"Malignant hyperthermia drill","hi":"मैलिग्नेंट हाइपरथर्मिया ड्रिल"},"scenario":{"en":"A 22-year-old man, 70 kg, is having a laparoscopic appendicectomy. Induction used propofol and suxamethonium, and anaesthesia is maintained with sevoflurane. Forty minutes in, the end-tidal CO2 keeps rising. Teaching scenario, not a real patient.","hi":"22 वर्षीय पुरुष, 70 kg, की लैप्रोस्कोपिक एपेंडिसेक्टॉमी हो रही है। इंडक्शन प्रोपोफोल और सक्सामेथोनियम से हुआ, और एनेस्थीसिया सेवोफ्लुरेन पर चल रहा है। 40 मिनट बाद end-tidal CO2 लगातार बढ़ रहा है। यह शिक्षण परिदृश्य है, असली मरीज़ नहीं।"},"sources":[{"label":"StewardMD Clinical Protocols: Malignant hyperthermia crisis","path":"kb/clinical-protocols/malignant-hyperthermia.json"},{"label":"European Malignant Hyperthermia Group. Recognising and managing a malignant hyperthermia crisis (v2024)","url":"https://www.emhg.org/recommendations-1/2024/11/4/recognising-and-managing-a-malignant-hyperthermia-crisis-v2024"}],"stages":[{"id":"recognise","src":0,"timeSec":60,"vitals":{"hr":128,"bp":"150/88","temp":37.6,"etco2":{"label":{"en":"EtCO2 (mmHg)","hi":"EtCO2 (mmHg)"},"value":62}},"prompt":{"en":"EtCO2 has risen from 38 to 62 mmHg although you doubled the minute ventilation. HR 128/min, the soda lime is hot. What is your diagnosis and first move?","hi":"मिनट वेंटिलेशन दोगुना करने के बावजूद EtCO2 38 से 62 mmHg हो गया। HR 128/min, सोडा लाइम गर्म है। आपका निदान और पहला कदम क्या है?"},"options":[{"id":"a","correct":true,"critical":true,"next":"triggers","text":{"en":"Suspect MH. Declare an emergency, call for help, get dantrolene and the MH kit, and ask the surgeon to finish fast.","hi":"MH का संदेह करें। इमरजेंसी घोषित करें, मदद बुलाएँ, डैंट्रोलीन और MH किट मँगाएँ, और सर्जन से जल्दी खत्म करने को कहें।"},"feedback":{"en":"Unexplained rising EtCO2 despite more ventilation, with tachycardia, is an early MH sign. Fever often comes late.","hi":"ज़्यादा वेंटिलेशन के बावजूद बिना कारण बढ़ता EtCO2, तेज़ नाड़ी के साथ, MH का शुरुआती संकेत है। बुखार अक्सर देर से आता है।"}},{"id":"b","correct":false,"next":"late","text":{"en":"It is CO2 absorbed from the pneumoperitoneum. Ventilate harder and carry on.","hi":"यह न्यूमोपेरिटोनियम से सोखा गया CO2 है। और तेज़ वेंटिलेट करें और जारी रखें।"},"feedback":{"en":"Laparoscopic CO2 is a differential, but EtCO2 that climbs despite doubled ventilation with tachycardia must be treated as MH.","hi":"लैप्रोस्कोपिक CO2 एक संभावना है, पर दोगुने वेंटिलेशन के बावजूद बढ़ता EtCO2 और तेज़ नाड़ी को MH मानकर इलाज करें।"}},{"id":"c","correct":false,"next":"late","text":{"en":"Wait for the temperature to rise before calling it MH.","hi":"MH कहने से पहले तापमान बढ़ने का इंतज़ार करें।"},"feedback":{"en":"Waiting for hyperthermia is a classic pitfall. Rising EtCO2 and tachycardia come first.","hi":"बुखार का इंतज़ार एक आम गलती है। बढ़ता EtCO2 और तेज़ नाड़ी पहले आते हैं।"}}]},{"id":"late","src":0,"timeSec":45,"vitals":{"hr":146,"bp":"96/60","temp":39.4,"k":{"label":{"en":"K+ (mmol/L)","hi":"K+ (mmol/L)"},"value":6.4}},"prompt":{"en":"Fifteen minutes later: temperature 39.4, K+ 6.4 mmol/L, ventricular ectopics and a rigid jaw. What now?","hi":"15 मिनट बाद: तापमान 39.4, K+ 6.4 mmol/L, वेंट्रिकुलर एक्टोपिक्स और सख्त जबड़ा। अब क्या?"},"options":[{"id":"a","correct":true,"next":"triggers","text":{"en":"Declare an MH crisis now, call for help and get dantrolene.","hi":"अभी MH संकट घोषित करें, मदद बुलाएँ और डैंट्रोलीन मँगाएँ।"},"feedback":{"en":"These are late signs. Every minute of delay raises the risk of arrest and DIC.","hi":"ये देर के संकेत हैं। हर मिनट की देरी से अरेस्ट और DIC का खतरा बढ़ता है।"}},{"id":"b","correct":false,"next":"triggers","text":{"en":"Give paracetamol for the fever.","hi":"बुखार के लिए पैरासिटामोल दें।"},"feedback":{"en":"Paracetamol does not stop the muscle hypermetabolism. Dantrolene does.","hi":"पैरासिटामोल मांसपेशियों के हाइपरमेटाबोलिज़्म को नहीं रोकता। डैंट्रोलीन रोकता है।"}}]},{"id":"triggers","src":0,"timeSec":60,"prompt":{"en":"Help is coming. What do you do with the anaesthetic machine and ventilation?","hi":"मदद आ रही है। एनेस्थीसिया मशीन और वेंटिलेशन के साथ क्या करेंगे?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Remove the vaporiser and give 100% O2 at high fresh gas flow (at least 10 L/min). Hyperventilate at 2 to 3 times normal minute volume.","hi":"वेपोराइज़र हटाएँ, 100% O2 हाई फ़्रेश गैस फ़्लो (कम से कम 10 L/min) पर दें, और सामान्य मिनट वॉल्यूम के 2 से 3 गुना पर हाइपरवेंटिलेट करें।"},"feedback":{"en":"Stop all triggers. Add activated charcoal filters to both limbs if you have them.","hi":"सभी ट्रिगर बंद करें। अगर हों तो दोनों लिम्ब में एक्टिवेटेड चारकोल फ़िल्टर लगाएँ।"}},{"id":"b","correct":false,"text":{"en":"Change to a fresh anaesthetic machine and circuit before anything else.","hi":"सबसे पहले नई एनेस्थीसिया मशीन और सर्किट लगाएँ।"},"feedback":{"en":"Do not waste time changing the machine. Remove the vaporiser and give dantrolene.","hi":"मशीन बदलने में समय बर्बाद न करें। वेपोराइज़र हटाएँ और डैंट्रोलीन दें।"}},{"id":"c","correct":false,"text":{"en":"Switch from sevoflurane to isoflurane.","hi":"सेवोफ्लुरेन से आइसोफ्लुरेन पर बदलें।"},"feedback":{"en":"All volatile agents trigger MH. Stop them all.","hi":"सभी वोलेटाइल एजेंट MH ट्रिगर करते हैं। सब बंद करें।"}}]},{"id":"maintain","src":0,"timeSec":45,"prompt":{"en":"He still needs anaesthesia while the surgeon closes. How?","hi":"सर्जन के बंद करने तक उसे एनेस्थीसिया चाहिए। कैसे?"},"options":[{"id":"a","correct":true,"text":{"en":"TIVA: propofol, an opioid and a non-depolarising blocker.","hi":"TIVA: प्रोपोफोल, एक ओपिओइड और नॉन-डिपोलराइज़िंग ब्लॉकर।"},"feedback":{"en":"These are non-trigger agents. Avoid any volatile and any further suxamethonium.","hi":"ये ट्रिगर न करने वाली दवाएँ हैं। कोई भी वोलेटाइल और दोबारा सक्सामेथोनियम न दें।"}},{"id":"b","correct":false,"text":{"en":"Another dose of suxamethonium for the rigidity.","hi":"सख्ती के लिए सक्सामेथोनियम की एक और खुराक।"},"feedback":{"en":"Suxamethonium is a trigger. Never repeat it in MH.","hi":"सक्सामेथोनियम ट्रिगर है। MH में इसे कभी न दोहराएँ।"}}]},{"id":"dantrolene","src":0,"timeSec":60,"prompt":{"en":"Dantrolene 20 mg vials have arrived. He weighs 70 kg. What is the first dose and how is it mixed?","hi":"डैंट्रोलीन 20 mg की शीशियाँ आ गई हैं। उसका वज़न 70 kg है। पहली खुराक कितनी और कैसे घोलें?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"2.5 mg/kg (175 mg), as a rapid IV bolus through a large-bore line. Each vial takes 60 mL sterile water. That is about 9 vials.","hi":"2.5 mg/kg (175 mg), बड़े कैनुला से तेज़ IV बोलस। हर शीशी में 60 mL स्टेराइल वॉटर। लगभग 9 शीशियाँ।"},"feedback":{"en":"A 70 kg adult needs 7 to 9 vials per dose. Use sterile water, not saline or glucose, and give each syringe as soon as it is ready.","hi":"70 kg वयस्क को हर खुराक में 7 से 9 शीशियाँ चाहिए। स्टेराइल वॉटर ही लें, सलाइन या ग्लूकोज़ नहीं, और हर सिरिंज तैयार होते ही दें।"}},{"id":"b","correct":false,"text":{"en":"2.5 mg/kg, each vial mixed in 0.9% saline.","hi":"2.5 mg/kg, हर शीशी 0.9% सलाइन में घोलें।"},"feedback":{"en":"The dose is right, but dantrolene is reconstituted with sterile water, not saline or glucose.","hi":"खुराक सही है, पर डैंट्रोलीन स्टेराइल वॉटर में घोला जाता है, सलाइन या ग्लूकोज़ में नहीं।"}},{"id":"c","correct":false,"text":{"en":"One 20 mg vial now, then see.","hi":"अभी एक 20 mg शीशी, फिर देखें।"},"feedback":{"en":"Under-dosing is a known pitfall. Give the full 2.5 mg/kg as a rapid bolus.","hi":"कम खुराक एक जानी-मानी गलती है। पूरी 2.5 mg/kg तेज़ बोलस में दें।"}}]},{"id":"repeat","src":0,"timeSec":60,"vitals":{"hr":134,"temp":38.9,"etco2":{"label":{"en":"EtCO2 (mmHg)","hi":"EtCO2 (mmHg)"},"value":70}},"prompt":{"en":"Five minutes after the first dose, EtCO2 is still 70 mmHg. Mixing is slow. Next?","hi":"पहली खुराक के 5 मिनट बाद भी EtCO2 70 mmHg है। घोलना धीमा चल रहा है। अगला?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Put two or more people on mixing. Give 1 mg/kg IV every 5 minutes until EtCO2 falls and temperature starts falling.","hi":"घोलने पर दो या ज़्यादा लोग लगाएँ। EtCO2 गिरने और तापमान घटने तक हर 5 मिनट पर 1 mg/kg IV दें।"},"feedback":{"en":"Association of Anaesthetists 2020 regimen. EMHG repeats the full dose every 10 minutes instead. Reappraise the diagnosis at 10 mg/kg.","hi":"Association of Anaesthetists 2020 की खुराक। EMHG इसकी जगह हर 10 मिनट पर पूरी खुराक दोहराता है। 10 mg/kg पर निदान दोबारा परखें।"}},{"id":"b","correct":false,"text":{"en":"Wait 30 minutes for the first dose to work.","hi":"पहली खुराक के असर के लिए 30 मिनट इंतज़ार करें।"},"feedback":{"en":"Keep giving dantrolene until the crisis is controlled. Waiting lets it progress.","hi":"संकट नियंत्रित होने तक डैंट्रोलीन देते रहें। इंतज़ार से यह बढ़ता है।"}}]},{"id":"potassium","src":0,"timeSec":60,"vitals":{"hr":138,"bp":"100/64","k":{"label":{"en":"K+ (mmol/L)","hi":"K+ (mmol/L)"},"value":6.6}},"prompt":{"en":"K+ is 6.6 mmol/L with peaked T waves. How do you treat it?","hi":"K+ 6.6 mmol/L है और T तरंगें नुकीली हैं। इलाज कैसे करेंगे?"},"options":[{"id":"a","correct":true,"critical":true,"next":"cool","text":{"en":"Calcium chloride 10 mg/kg IV (max 2 g), then insulin 10 units with 50 mL of 50% glucose.","hi":"कैल्शियम क्लोराइड 10 mg/kg IV (max 2 g), फिर इंसुलिन 10 units के साथ 50% ग्लूकोज़ का 50 mL।"},"feedback":{"en":"Calcium protects the heart; insulin with glucose shifts potassium into cells. Add haemofiltration if it stays refractory.","hi":"कैल्शियम हृदय की रक्षा करता है; ग्लूकोज़ के साथ इंसुलिन पोटैशियम को कोशिकाओं में ले जाता है। न सुधरे तो हीमोफ़िल्ट्रेशन जोड़ें।"}},{"id":"b","correct":false,"next":"ccb","text":{"en":"Verapamil to slow the heart rate.","hi":"हृदय गति धीमी करने के लिए वेरापामिल।"},"feedback":{"en":"Calcium channel blockers interact with dantrolene. Do not use them in MH.","hi":"कैल्शियम चैनल ब्लॉकर डैंट्रोलीन के साथ प्रतिक्रिया करते हैं। MH में इनका उपयोग न करें।"}}]},{"id":"ccb","src":0,"timeSec":30,"vitals":{"hr":120,"bp":"70/40"},"prompt":{"en":"After verapamil his BP falls to 70/40 mmHg and K+ is still high. What now?","hi":"वेरापामिल के बाद BP 70/40 mmHg हो गया और K+ अब भी ऊँचा है। अब क्या?"},"options":[{"id":"a","correct":true,"next":"cool","text":{"en":"Give calcium chloride and insulin with glucose now, and support the BP. No more calcium channel blockers.","hi":"अभी कैल्शियम क्लोराइड और ग्लूकोज़ के साथ इंसुलिन दें, और BP सँभालें। और कैल्शियम चैनल ब्लॉकर नहीं।"},"feedback":{"en":"Correct recovery. For arrhythmias in MH use amiodarone, magnesium or a beta-blocker.","hi":"सही सुधार। MH में अरिद्मिया के लिए एमियोडेरोन, मैग्नीशियम या बीटा-ब्लॉकर लें।"}},{"id":"b","correct":false,"next":"cool","text":{"en":"Repeat the verapamil.","hi":"वेरापामिल दोहराएँ।"},"feedback":{"en":"That deepens the shock. Treat the potassium with calcium and insulin.","hi":"इससे शॉक बढ़ेगा। पोटैशियम का इलाज कैल्शियम और इंसुलिन से करें।"}}]},{"id":"cool","src":0,"timeSec":60,"vitals":{"temp":39.6,"hr":130},"prompt":{"en":"Core temperature is 39.6. How do you cool him, and when do you stop?","hi":"कोर तापमान 39.6 है। उसे कैसे ठंडा करेंगे, और कब रोकेंगे?"},"options":[{"id":"a","correct":true,"text":{"en":"2000 to 3000 mL of chilled IV crystalloid at 4 to 8 C plus surface cooling. Stop once core temperature is below 38.5 C.","hi":"2000 से 3000 mL ठंडा IV क्रिस्टलॉइड, 4 से 8 C पर, साथ में सतह से ठंडक। कोर तापमान 38.5 C से नीचे आते ही रोकें।"},"feedback":{"en":"Stopping at 38.5 C avoids overshoot into hypothermia.","hi":"38.5 C पर रोकने से तापमान ज़रूरत से ज़्यादा नहीं गिरता।"}},{"id":"b","correct":false,"text":{"en":"Cool actively until he reaches 35 C.","hi":"35 C तक सक्रिय रूप से ठंडा करें।"},"feedback":{"en":"That overshoots. Stop active cooling once core temperature is below 38.5 C.","hi":"इससे तापमान ज़्यादा गिर जाएगा। कोर तापमान 38.5 C से नीचे आते ही सक्रिय ठंडक रोकें।"}}]},{"id":"after","src":0,"timeSec":60,"vitals":{"temp":38.2,"hr":104,"urineMl":60},"prompt":{"en":"EtCO2 and temperature are falling. His urine is dark. Where does he go and what follows?","hi":"EtCO2 और तापमान गिर रहे हैं। उसका मूत्र गहरा है। वह कहाँ जाएगा और आगे क्या?"},"options":[{"id":"a","correct":true,"critical":true,"next":"end","text":{"en":"ICU for at least 24 hours, with urine above 2 mL/kg/h for myoglobinuria. Label him MH-susceptible and refer the family for testing.","hi":"कम से कम 24 घंटे ICU, मायोग्लोबिन्यूरिया के लिए मूत्र 2 mL/kg/h से ऊपर, फिर उसे MH-susceptible लिखें और परिवार को जाँच के लिए भेजें।"},"feedback":{"en":"About 25% relapse, and relapse can be fatal. Watch CK, potassium, kidneys and clotting.","hi":"लगभग 25% में दोबारा होता है, और यह जानलेवा हो सकता है। CK, पोटैशियम, गुर्दे और क्लॉटिंग पर नज़र रखें।"}},{"id":"b","correct":false,"next":"end","text":{"en":"Recovery for 1 hour, then the surgical ward.","hi":"1 घंटा रिकवरी, फिर सर्जिकल वार्ड।"},"feedback":{"en":"Discharge to a ward too early is a pitfall. Relapse can occur within 24 hours.","hi":"जल्दी वार्ड भेजना एक गलती है। 24 घंटे के भीतर दोबारा हो सकता है।"}}]}]});
  if (node) module.exports = model;
  else (G.NARKE_MODELS = G.NARKE_MODELS || {})[model.id] = model;
